def solve_golomb(n, length):
    marks = [0] * n
    diffs = [False] * (length + 1)

    def backtrack(idx, current_marks, current_diffs):
        if idx == n:
            return current_marks

        last_mark = current_marks[idx-1]
        for next_mark in range(last_mark + 1, length - (n - 1 - idx) + 1):
            new_diffs = []
            possible = True
            for i in range(idx):
                diff = next_mark - current_marks[i]
                if current_diffs[diff]:
                    possible = False
                    break
                new_diffs.append(diff)

            if possible:
                for d in new_diffs:
                    current_diffs[d] = True

                res = backtrack(idx + 1, current_marks + [next_mark], current_diffs)
                if res:
                    return res

                for d in new_diffs:
                    current_diffs[d] = False
        return None

    return backtrack(1, [0], [False] * (length + 1))

